/// Returns the cross product of \p v1 and \p v2.
inline GfVec3d
GfCross(GfVec3d const &v1, GfVec3d const &v2)
{
    return GfVec3d(
        v1.y * v2.z - v1.z * v2.y,
        v1.z * v2.x - v1.x * v2.z,
        v1.x * v2.y - v1.y * v2.x);
}

/// Returns the cross product of \p v1 and \p v2. 
/// \see GfCross()
inline GfVec3d
operator^(GfVec3d const &v1, GfVec3d const &v2)
{
    return GfCross(v1, v2);
}

